11	export function registerAuctionHandlers(io: Server, socket: Socket): void {
12	  // Event: auction:start
13	  socket.on("auction:start", async () => {
14	    try {
15	      const participant = socket.data.participant;
16	      const room = socket.data.room;
17	
18	      if (!participant || !room) {
19	        socket.emit("error", { message: "Not authenticated for any room." });
20	        return;
21	      }
22	
23	      // 1. Verify user is admin
24	      if (participant.role !== "admin") {
25	        socket.emit("error", { message: "Access denied: Only the room administrator can start the auction." });
26	        return;
27	      }
28	
29	      // 2. Fetch fresh Room document and verify status
30	      const freshRoom = await Room.findById(room._id);
31	      if (!freshRoom) {
32	        socket.emit("error", { message: "Room not found." });
33	        return;
34	      }
35	
36	      if (freshRoom.status !== "lobby") {
37	        socket.emit("error", { message: "Auction has already started or completed." });
38	        return;
39	      }
40	
41	      // 3. Select first pending item
42	      const pendingItems = await AuctionItem.find({
43	        roomId: freshRoom._id,
44	        status: "pending",
45	      }).sort({ createdAt: 1 });
46	
47	      if (pendingItems.length === 0) {
