     5	const INITIAL_RETRY_DELAY_MS = 1_000;
     6	const MAX_RETRY_DELAY_MS = 30_000;
     7	const SERVER_SELECTION_TIMEOUT_MS = 10_000;
     8	
     9	// Fail a buffered query in 5s instead of Mongoose's 10s default, so requests
    10	// that slip past the readiness guard surface an error quickly.
    11	mongoose.set("bufferTimeoutMS", 5_000);
    12	
    13	export type DatabaseStatus =
    14	  | "connected"
    15	  | "connecting"
    16	  | "disconnecting"
    17	  | "disconnected";
    18	
    19	const READY_STATE_LABELS: Record<number, DatabaseStatus> = {
    20	  0: "disconnected",
    21	  1: "connected",
    22	  2: "connecting",
    23	  3: "disconnecting",
    24	};
    25	
    26	export function getDatabaseStatus(): DatabaseStatus {
    27	  return READY_STATE_LABELS[mongoose.connection.readyState] ?? "disconnected";
    28	}
    29	
    30	export function isDatabaseConnected(): boolean {
    31	  return mongoose.connection.readyState === 1;
    32	}
    33	
    34	function sleep(ms: number): Promise<void> {
    35	  return new Promise((resolve) => setTimeout(resolve, ms));
    36	}
    37	
    38	async function migrateParticipantUsernameKeys(): Promise<void> {
    39	  await Participant.collection.updateMany(
    40	    { usernameNormalized: { $exists: false } },
    41	    [{ $set: { usernameNormalized: { $toLower: "$username" } } }],
    42	  );
    43	  await Participant.createIndexes();
    44	}
    45	
    46	function registerConnectionLogging(): void {
    47	  mongoose.connection.on("connected", () => {
    48	    console.log("Successfully connected to MongoDB.");
    49	  });
    50	
    51	  mongoose.connection.on("error", (err: Error) => {
    52	    console.error(`MongoDB connection error: ${err.message}`);
    53	  });
    54	
    55	  mongoose.connection.on("disconnected", () => {
    56	    console.warn("MongoDB disconnected. Mongoose will reconnect automatically.");
    57	  });
    58	}
    59	
    60	/**
    61	 * Connects to MongoDB in the background, retrying with exponential backoff until
    62	 * the first connection succeeds. Resolves once the database is usable.
    63	 *
    64	 * This never rejects and never exits the process: an unreachable database must
    65	 * degrade the API, not prevent the HTTP server from binding its port. Mongoose
    66	 * handles reconnection on its own after this initial connection is established,
    67	 * so the retry loop only covers cold start.
    68	 */
    69	export async function connectDB(): Promise<void> {
    70	  registerConnectionLogging();
    71	
    72	  let delay = INITIAL_RETRY_DELAY_MS;
    73	
    74	  for (let attempt = 1; ; attempt += 1) {
    75	    try {
    76	      await mongoose.connect(env.mongodbUri, {
    77	        serverSelectionTimeoutMS: SERVER_SELECTION_TIMEOUT_MS,
    78	      });
    79	      await migrateParticipantUsernameKeys();
    80	      return;
    81	    } catch (error) {
    82	      const message = error instanceof Error ? error.message : String(error);
    83	      console.error(
    84	        `MongoDB connection attempt ${attempt} failed (${message}). ` +
    85	          `Retrying in ${Math.round(delay / 1000)}s.`,
    86	      );
    87	
    88	      await sleep(delay);
    89	      delay = Math.min(delay * 2, MAX_RETRY_DELAY_MS);
    90	    }
    91	  }
    92	}
