    13	export function errorHandler(
    14	  err: Error,
    15	  _req: Request,
    16	  res: Response,
    17	  _next: NextFunction,
    18	) {
    19	  const isDuplicateKey = "code" in err && err.code === 11000;
    20	  const statusCode = err instanceof AppError ? err.statusCode : isDuplicateKey ? 409 : err instanceof mongoose.Error.ValidationError ? 400 : 500;
    21	  const message = err instanceof AppError
    22	    ? err.message
    23	    : isDuplicateKey
    24	      ? "A record with these details already exists."
    25	      : err instanceof mongoose.Error.ValidationError
    26	        ? "Invalid request data."
    27	        : "Internal server error";
    28	
    29	  res.status(statusCode).json({ error: message });
    30	}
