     1	import type { NextFunction, Request, Response } from "express";
     2	import { isDatabaseConnected } from "../config/db.js";
     3	import { AppError } from "./errorHandler.js";
     4	
     5	/**
     6	 * Rejects API requests while the database is unreachable.
     7	 *
     8	 * Without this, requests made during a database outage sit in Mongoose's write
     9	 * buffer until it times out, which reads to the client as a hung request. A
    10	 * fast, explicit 503 lets the frontend show a real error state instead.
    11	 */
    12	export function requireDatabase(
    13	  _req: Request,
    14	  _res: Response,
    15	  next: NextFunction,
    16	) {
    17	  if (!isDatabaseConnected()) {
    18	    next(
    19	      new AppError(
    20	        "The server cannot reach its database right now. Please retry in a moment.",
    21	        503,
    22	      ),
    23	    );
    24	    return;
    25	  }
    26	
    27	  next();
    28	}
