     6	function generateRandomCode(length = 6): string {
     7	  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
     8	  let result = "";
     9	  for (let i = 0; i < length; i++) {
    10	    result += chars.charAt(Math.floor(Math.random() * chars.length));
    11	  }
    12	  return result;
    13	}
