    15	/**
    16	 * Generates a unique 6-character room code by verifying uniqueness in the database.
    17	 */
    18	export async function generateUniqueRoomCode(): Promise<string> {
    19	  const maxAttempts = 10;
    20	  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    21	    const code = generateRandomCode();
    22	    const existingRoom = await Room.findOne({ code });
    23	    if (!existingRoom) {
    24	      return code;
    25	    }
    26	  }
    27	  throw new Error("Failed to generate a unique room code after multiple attempts.");
    28	}
