    38	async function migrateParticipantUsernameKeys(): Promise<void> {
    39	  await Participant.collection.updateMany(
    40	    { usernameNormalized: { $exists: false } },
    41	    [{ $set: { usernameNormalized: { $toLower: "$username" } } }],
