    60	/**
    61	 * Connects to MongoDB in the background, retrying with exponential backoff until
    62	 * the first connection succeeds. Resolves once the database is usable.
    63	 *
    64	 * This never rejects and never exits the process: an unreachable database must
    65	 * degrade the API, not prevent the HTTP server from binding its port. Mongoose
    66	 * handles reconnection on its own after this initial connection is established,
    67	 * so the retry loop only covers cold start.
    68	 */
    69	export async function connectDB(): Promise<void> {
    70	  registerConnectionLogging();
    71	
    72	  let delay = INITIAL_RETRY_DELAY_MS;
    73	
    74	  for (let attempt = 1; ; attempt += 1) {
    75	    try {
    76	      await mongoose.connect(env.mongodbUri, {
    77	        serverSelectionTimeoutMS: SERVER_SELECTION_TIMEOUT_MS,
    78	      });
    79	      await migrateParticipantUsernameKeys();
    80	      return;
    81	    } catch (error) {
    82	      const message = error instanceof Error ? error.message : String(error);
    83	      console.error(
    84	        `MongoDB connection attempt ${attempt} failed (${message}). ` +
    85	          `Retrying in ${Math.round(delay / 1000)}s.`,
    86	      );
    87	
    88	      await sleep(delay);
    89	      delay = Math.min(delay * 2, MAX_RETRY_DELAY_MS);
    90	    }
    91	  }
    92	}
