    13	/**
    14	 * Optional authentication middleware.
    15	 * If a JWT token cookie is present, verifies it and populates req.user.
    16	 * Does not block the request if authentication is missing.
    17	 */
    18	export function optionalAuth(
    19	  req: AuthenticatedRequest,
    20	  _res: Response,
    21	  next: NextFunction,
    22	): void {
    23	  try {
    24	    const token = req.cookies.token;
    25	
    26	    if (!token) {
    27	      return next();
    28	    }
    29	
    30	    try {
    31	      const decoded = jwt.verify(token, env.jwtSecret) as {
    32	        username: string;
    33	        role: "admin" | "participant";
    34	      };
    35	      req.user = decoded;
    36	    } catch (err) {
    37	      // Stale or invalid cookie -> ignore and continue
    38	    }
    39	    next();
    40	  } catch (error) {
    41	    next(error);
    42	  }
    43	}
    44	
    45	/**
    46	 * Reads the room-scoped participant session token (issued on room create/join)
    47	 * from request headers and attaches it to req.sessionToken. Does not verify
    48	 * the token against a participant — the service layer looks it up and
    49	 * enforces role checks, matching how every other room-scoped write is done.
    50	 */
    51	export function extractSessionToken(
    52	  req: AuthenticatedRequest,
    53	  _res: Response,
    54	  next: NextFunction,
    55	): void {
    56	  const headerToken =
    57	    req.headers["x-session-token"] ?? req.headers["session-token"];
    58	  const authHeader = req.headers["authorization"];
    59	
    60	  if (headerToken) {
    61	    req.sessionToken = Array.isArray(headerToken)
    62	      ? headerToken[0]
    63	      : headerToken;
    64	  } else if (
    65	    typeof authHeader === "string" &&
    66	    authHeader.startsWith("Bearer ")
    67	  ) {
    68	    req.sessionToken = authHeader.slice(7);
    69	  }
    70	
    71	  next();
    72	}
