    10	type InitStatus = "loading" | "ready" | "unavailable";
    11	
    12	// How long to wait before telling the user a slow start is expected rather than broken.
    13	const SLOW_START_NOTICE_MS = 4_000;
    14	
    15	export function AuthInitializer({ children }: Props) {
    16	  const setAuthUser = useSessionStore((state) => state.setAuthUser);
    17	  const [status, setStatus] = useState<InitStatus>("loading");
    18	  const [isSlow, setIsSlow] = useState(false);
    19	
    20	  const initialise = useCallback(async () => {
    21	    setStatus("loading");
    22	    setIsSlow(false);
    23	
    24	    try {
    25	      const data = await checkAuth();
    26	      setAuthUser(data.user ?? null);
    27	      setStatus("ready");
    28	    } catch (error) {
    29	      // An unreachable backend is not the same as a signed-out user: rendering the
    30	      // app would leave every subsequent request failing with no explanation.
    31	      if (error instanceof ApiUnavailableError) {
    32	        setStatus("unavailable");
    33	        return;
    34	      }
    35	
    36	      setAuthUser(null);
    37	      setStatus("ready");
    38	    }
    39	  }, [setAuthUser]);
    40	
    41	  useEffect(() => {
    42	    void initialise();
    43	  }, [initialise]);
    44	
    45	  useEffect(() => {
    46	    if (status !== "loading") return;
    47	
    48	    const timer = setTimeout(() => setIsSlow(true), SLOW_START_NOTICE_MS);
    49	    return () => clearTimeout(timer);
    50	  }, [status]);
    51	
    52	  if (status === "loading") {
    53	    return (
    54	      <div className="flex h-screen flex-col items-center justify-center gap-3 bg-black px-6 text-center text-white">
    55	        <div
    56	          className="h-6 w-6 animate-spin rounded-full border-2 border-white/20 border-t-white"
    57	          aria-hidden="true"
    58	        />
    59	        <p className="text-sm text-white/70">Loading your session</p>
    60	        {isSlow && (
    61	          <p className="max-w-sm text-xs text-white/40">
    62	            The server sleeps when idle on the free tier, so the first request can
    63	            take up to a minute to wake it.
    64	          </p>
    65	        )}
    66	      </div>
    67	    );
    68	  }
    69	
    70	  if (status === "unavailable") {
    71	    return (
    72	      <div className="flex h-screen flex-col items-center justify-center gap-4 bg-black px-6 text-center text-white">
    73	        <h1 className="text-lg font-semibold">Can&apos;t reach the server</h1>
    74	        <p className="max-w-sm text-sm text-white/60">
    75	          The auction service is not responding. It may still be starting up, or it
    76	          may be temporarily down.
    77	        </p>
    78	        <Button onClick={() => void initialise()}>Try again</Button>
    79	      </div>
