     1	import { io, Socket } from "socket.io-client";
     2	
     3	const rawApiUrl = import.meta.env.VITE_API_URL ?? "http://localhost:3001/api";
     4	const sanitizedBaseUrl = rawApiUrl.replace(/\/$/, "");
     5	const SOCKET_URL = sanitizedBaseUrl.endsWith("/api") ? sanitizedBaseUrl.slice(0, -4) : sanitizedBaseUrl;
     6	
     7	let socket: Socket | null = null;
     8	let activeConnection: { roomCode: string; sessionToken: string } | null = null;
     9	
    10	/**
    11	 * Connects the socket to the backend server with handshake authentication parameters.
    12	 */
    13	export function connectSocket(roomCode: string, sessionToken: string): Socket {
    14	  const requestedConnection = { roomCode: roomCode.toUpperCase(), sessionToken };
    15	
    16	  // Never reuse an authenticated socket for a different room or participant.
    17	  if (socket) {
    18	    if (
    19	      activeConnection?.roomCode === requestedConnection.roomCode &&
    20	      activeConnection.sessionToken === requestedConnection.sessionToken
    21	    ) {
    22	      if (!socket.connected) socket.connect();
    23	      return socket;
    24	    }
    25	
    26	    socket.disconnect();
    27	    socket = null;
    28	  }
    29	
    30	  socket = io(SOCKET_URL, {
    31	    auth: {
    32	      roomCode: requestedConnection.roomCode,
    33	      sessionToken,
    34	    },
    35	    autoConnect: true,
    36	    reconnection: true,
    37	    reconnectionAttempts: 5,
    38	    reconnectionDelay: 1000,
    39	  });
    40	  activeConnection = requestedConnection;
    41	
    42	  return socket;
    43	}
    44	
    45	/**
    46	 * Disconnects the socket connection and cleans up the instance.
    47	 */
    48	export function disconnectSocket(): void {
    49	  if (socket) {
    50	    socket.disconnect();
    51	    socket = null;
    52	    activeConnection = null;
    53	  }
    54	}
    55	
    56	/**
    57	 * Returns the active socket instance.
    58	 */
    59	export function getSocket(): Socket | null {
    60	  return socket;
    61	}
