1	import { useState, useEffect, useCallback } from "react";
2	import { useParams, useNavigate } from "react-router-dom";
3	import {
4	  Clock,
5	  Crown,
6	  Users,
7	  AlertCircle,
8	  Tag,
9	  MessageSquare,
10	  DollarSign,
11	  TrendingUp,
12	} from "lucide-react";
13	import { PageContainer } from "../../components/ui/PageContainer";
14	import { Button } from "../../components/ui/Button";
15	import { useSessionStore } from "../../stores/useSessionStore";
16	import { useSocket } from "../../hooks/useSocket";
17	import { getSocket } from "../../services/socket";
18	import type { AuctionItem, Bid } from "../../services/api";
19	
20	interface ToastMsg {
21	  id: string;
22	  message: string;
23	  type: "info" | "success" | "error";
24	}
25	
26	export function AuctionPage() {
27	  const { code } = useParams<{ code: string }>();
28	  const navigate = useNavigate();
29	
30	  const {
31	    roomCode: sessionRoomCode,
32	    username: sessionUsername,
33	    role: sessionRole,
34	    clearSession,
35	  } = useSessionStore();
36	
37	  // Connect to Socket.IO to track live bidding item, presence, and bids history
38	  const {
39	    status: socketStatus,
40	    room,
41	    participants,
42	    activeItem,
43	    bids,
44	    bidError,
45	    setBidError,
46	    error: socketError,
47	  } = useSocket(code || "");
48	
49	  const [bidVal, setBidVal] = useState("");
50	  const [localBidErr, setLocalBidErr] = useState<string | null>(null);
51	  
52	  const [toasts, setToasts] = useState<ToastMsg[]>([]);
53	  const [activityLogs, setActivityLogs] = useState<string[]>([]);
54	  const [clockNow, setClockNow] = useState(() => Date.now());
55	
56	  const addToast = useCallback((message: string, type: "info" | "success" | "error" = "info") => {
57	    const id = Math.random().toString(36).substr(2, 9);
58	    setToasts((prev) => [...prev, { id, message, type }]);
59	    setTimeout(() => {
60	      setToasts((prev) => prev.filter((t) => t.id !== id));
61	    }, 4000);
62	  }, []);
63	
64	  const minBidVal = activeItem ? (activeItem.currentBid ?? activeItem.startingBid ?? 0) + 1 : 1;
65	  const endsAtMs = room?.endsAt ? Date.parse(room.endsAt) : Number.NaN;
66	  const secondsRemaining = Number.isFinite(endsAtMs)
67	    ? Math.max(0, Math.ceil((endsAtMs - clockNow) / 1000))
68	    : 0;
69	
70	  useEffect(() => {
71	    if (!Number.isFinite(endsAtMs)) return;
72	    const interval = window.setInterval(() => setClockNow(Date.now()), 250);
73	    return () => window.clearInterval(interval);
74	  }, [endsAtMs]);
75	
76	  // Listen to live events for broadcast logs and toast notifications
77	  useEffect(() => {
78	    const socket = getSocket();
79	    if (!socket) return;
80	
81	    const handleItemEnded = (data: { item: AuctionItem; resolution: "sold" | "unsold" }) => {
82	      const username = data.item.highestBidderUsername || "none";
83	      const price = data.item.currentBid || data.item.startingBid;
84	      const formattedMsg = data.resolution === "sold"
85	        ? `${data.item.name} sold to ${username} for ₹${price.toLocaleString()}`
86	        : `${data.item.name} marked unsold`;
87	
88	      setActivityLogs((prev) => [...prev, `✦ ${formattedMsg}`]);
89	      addToast(formattedMsg, "info");
90	    };
91	
92	    const handleItemActivated = (data: { item: AuctionItem }) => {
93	      const msg = `Item ${data.item.name} is active. Minimum bid: ₹${(data.item.currentBid || data.item.startingBid).toLocaleString()}`;
94	      setActivityLogs((prev) => [...prev, `✦ ${msg}`]);
95	      addToast(`New item active: ${data.item.name}`, "info");
96	      setLocalBidErr(null);
97	      setBidVal("");
98	    };
99	
100	    const handleBidAccepted = (data: { bid: Bid }) => {
101	      const msg = `Bid of ₹${data.bid.amount.toLocaleString()} accepted for ${data.bid.username}`;
102	      setActivityLogs((prev) => [...prev, `✔ ${msg}.`]);
103	      addToast(`New bid: ₹${data.bid.amount.toLocaleString()} by ${data.bid.username}`, "success");
104	    };
105	
106	    const handleBidRejected = (data: { reason: string; minimumBid: number }) => {
107	      addToast(data.reason, "error");
108	    };
109	
110	    const handleServerError = (data: { message: string }) => addToast(data.message, "error");
111	
112	    socket.on("item:ended", handleItemEnded);
113	    socket.on("item:activated", handleItemActivated);
114	    socket.on("bid:accepted", handleBidAccepted);
115	    socket.on("bid:rejected", handleBidRejected);
116	    socket.on("error", handleServerError);
117	
118	    return () => {
119	      socket.off("item:ended", handleItemEnded);
120	      socket.off("item:activated", handleItemActivated);
121	      socket.off("bid:accepted", handleBidAccepted);
122	      socket.off("bid:rejected", handleBidRejected);
123	      socket.off("error", handleServerError);
124	    };
125	  }, [addToast]);
126	
127	  // Security check: Redirect if the user has no session or is in the wrong room
128	  const hasNoAccess = !sessionUsername || !sessionRole || sessionRoomCode !== code;
129	
130	  // Automatically navigate to results page when room transitions to completed status
131	  useEffect(() => {
132	    if (room?.status === "completed" && code) {
133	      navigate(`/results/${code}`);
134	    }
135	  }, [room?.status, code, navigate]);
136	
137	  const handleLeaveRoom = () => {
138	    clearSession();
139	    navigate("/");
140	  };
141	
142	  // Submit new bid (Participants only)
143	  const handleSubmitBid = (e: React.FormEvent) => {
144	    e.preventDefault();
145	    if (!activeItem) return;
146	
147	    const bidAmount = Number(bidVal);
148	    const currentPrice = activeItem.currentBid ?? activeItem.startingBid ?? 0;
149	    const minBidRequired = currentPrice + 1;
150	
151	    if (!Number.isFinite(bidAmount) || bidAmount < minBidRequired) {
152	      setLocalBidErr(`Bid must be at least ₹${minBidRequired.toLocaleString()}`);
153	      return;
154	    }
155	
156	    setLocalBidErr(null);
157	    setBidError(null);
158	
159	    const socket = getSocket();
160	    if (socket) {
161	      socket.emit("bid:place", { amount: bidAmount });
162	    }
163	    setBidVal(""); // Reset input field
164	  };
165	
166	  // Sell active item (Admin only)
167	  const handleSellItem = () => {
168	    const socket = getSocket();
169	    if (socket) {
170	      socket.emit("item:sell");
171	    }
172	  };
173	
174	  // Mark active item unsold (Admin only)
175	  const handleMarkUnsold = () => {
176	    const socket = getSocket();
177	    if (socket) {
178	      socket.emit("item:unsold");
179	    }
180	  };
181	
182	  const isLoading = !room && socketStatus === "connecting";
183	
184	  if (isLoading) {
185	    return (
186	      <PageContainer className="flex flex-col items-center justify-center min-h-[60vh] px-4">
187	        <div className="flex flex-col items-center gap-4 text-center">
188	          <div className="relative flex h-12 w-12 items-center justify-center">
189	            <div className="animate-ping absolute inline-flex h-full w-full rounded-full bg-accent/20 opacity-75" />
190	            <div className="relative rounded-full h-8 w-8 bg-accent/20 flex items-center justify-center">
191	              <Clock className="h-4 w-4 text-accent animate-spin" />
192	            </div>
193	          </div>
194	          <p className="text-sm text-text-secondary">Establishing live auction connection...</p>
195	        </div>
196	      </PageContainer>
197	    );
198	  }
199	
200	  if (socketError || (!room && socketStatus === "disconnected")) {
201	    return (
202	      <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
203	        <div className="border border-border bg-surface-raised/40 p-8 rounded-xl text-center max-w-md mx-auto space-y-6 shadow-xl">
204	          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-red-500/10 text-red-400">
205	            <AlertCircle className="h-6 w-6" />
206	          </div>
207	          <div className="space-y-2">
208	            <h2 className="text-xl font-semibold text-text-primary">Realtime Connection Failed</h2>
209	            <p className="text-sm text-text-secondary leading-relaxed">
210	              {socketError ?? "Failed to connect to the live auction room. Check if the server is running."}
211	            </p>
212	          </div>
213	          <Button variant="secondary" onClick={() => navigate("/")} className="w-full">
214	            Back to Home
215	          </Button>
216	        </div>
217	      </PageContainer>
218	    );
219	  }
220	
221	  if (hasNoAccess) {
222	    return (
223	      <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
224	        <div className="border border-border bg-surface-raised/40 p-8 rounded-xl text-center max-w-md mx-auto space-y-6 shadow-xl">
225	          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-accent/10 text-accent">
226	            <Users className="h-6 w-6" />
227	          </div>
228	          <div className="space-y-2">
229	            <h2 className="text-xl font-semibold text-text-primary">Access Denied</h2>
230	            <p className="text-sm text-text-secondary leading-relaxed">
231	              You are trying to access room <span className="font-mono text-accent font-semibold">{code}</span> but do not have an active session. Please register to join.
232	            </p>
233	          </div>
234	          <Button variant="primary" onClick={() => navigate(`/join?code=${code}`)} className="w-full">
235	            Join Room
236	          </Button>
237	        </div>
238	      </PageContainer>
239	    );
240	  }
241	
242	  const isAdmin = sessionRole === "admin";
243	
244	  return (
245	    <PageContainer className="px-4 py-12 sm:px-6 sm:py-16 max-w-5xl">
246	      <div className="space-y-8">
247	        
248	        {/* Connection status header */}
249	        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-border pb-6">
250	          <div className="space-y-1">
251	            <div className="flex items-center gap-2">
252	              <span className="inline-flex h-2 w-2 rounded-full bg-red-500 animate-pulse" />
253	              <span className="text-[10px] font-semibold uppercase tracking-wider text-red-500 mr-2">
254	                LIVE AUCTION
255	              </span>
256	              <span className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${secondsRemaining <= 10 ? "border-red-500/30 bg-red-500/10 text-red-400" : "border-accent/30 bg-accent/10 text-accent"}`}>
257	                <Clock className="h-3 w-3" />
258	                {secondsRemaining}s
259	              </span>
260	              {socketStatus === "connected" && (
261	                <span className="inline-flex items-center gap-1.5 rounded-full bg-green-500/10 border border-green-500/20 px-2 py-0.5 text-[10px] font-semibold text-green-400">
262	                  <span className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />
263	                  Synced
264	                </span>
265	              )}
266	              {socketStatus === "connecting" && (
267	                <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-500/10 border border-amber-500/20 px-2 py-0.5 text-[10px] font-semibold text-amber-400">
268	                  <span className="h-1.5 w-1.5 rounded-full bg-amber-500 animate-pulse" />
269	                  Reconnecting...
270	                </span>
271	              )}
272	            </div>
273	            <h1 className="text-2xl font-bold tracking-tight text-text-primary sm:text-3xl">
274	              {room?.name}
275	            </h1>
276	          </div>
277	
278	          <Button
279	            variant="ghost"
280	            onClick={handleLeaveRoom}
281	            className="self-start sm:self-center border border-border/50 text-xs text-text-secondary hover:text-red-400 hover:bg-red-500/10 hover:border-red-500/20"
282	          >
283	            Leave Room
284	          </Button>
285	        </div>
286	
287	        {/* Host Control center resolving controls (Visible to Admin only) */}
288	        {isAdmin && activeItem && (
289	          <div className="border border-amber-500/20 bg-amber-500/5 p-4 rounded-xl flex flex-col sm:flex-row items-center justify-between gap-4 shadow-sm">
290	            <div className="space-y-1 text-center sm:text-left">
291	              <h3 className="text-sm font-semibold text-amber-400 flex items-center justify-center sm:justify-start gap-1.5">
292	                <Crown className="h-4 w-4" />
293	                Host Resolution Console
294	              </h3>
295	              <p className="text-xs text-text-secondary">
296	                Resolve the current item's bid. The next pending item in queue will activate automatically.
297	              </p>
298	            </div>
299	            <div className="flex gap-2 w-full sm:w-auto">
300	              <Button
301	                onClick={handleSellItem}
302	                variant="primary"
303	                className="flex-1 sm:flex-initial bg-green-500 hover:bg-green-600 border-green-500/20 text-zinc-950 font-bold text-xs"
304	              >
305	                Sell Item (₹{(activeItem.currentBid ?? activeItem.startingBid ?? 0).toLocaleString()})
306	              </Button>
307	              <Button
308	                onClick={handleMarkUnsold}
309	                variant="secondary"
310	                className="flex-1 sm:flex-initial text-xs border border-border/50"
311	              >
312	                Mark Unsold
313	              </Button>
314	            </div>
315	          </div>
316	        )}
317	
318	        {/* Live Auction Board Layout */}
319	        <div className="grid gap-6 md:grid-cols-3 items-start">
320	          
321	          {/* Active Item Container (2/3 width) */}
322	          <div className="md:col-span-2 space-y-6">
323	            
324	            {/* Current Item Presentation */}
325	            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-6 shadow-lg relative overflow-hidden">
326	              <div className="absolute top-0 right-0 h-32 w-32 rounded-full bg-accent/5 blur-[30px] pointer-events-none" />
327	              
328	              <div className="flex items-center justify-between border-b border-border/40 pb-4">
329	                <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2">
330	                  <Tag className="h-4 w-4 text-accent" />
331	                  Active Auction Item
332	                </span>
333	                {activeItem && secondsRemaining > 0 && (
334	                  <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider text-green-400 bg-green-500/15 border border-green-500/30 px-2.5 py-0.5 rounded-full">
335	                    Bidding Open
336	                  </span>
337	                )}
338	              </div>
339	
340	              {!activeItem ? (
341	                <div className="py-12 text-center space-y-3">
342	                  <Clock className="h-10 w-10 text-text-muted mx-auto animate-pulse" />
343	                  <h3 className="text-base font-semibold text-text-primary">Waiting for item activation...</h3>
344	                  <p className="text-xs text-text-secondary max-w-sm mx-auto">
345	                    The host is resolving items. Bidding will open immediately once the next item activates.
346	                  </p>
347	                </div>
348	              ) : (
349	                <div className="space-y-6">
350	                  <div className="space-y-2">
351	                    <h2 className="text-xl font-bold text-text-primary tracking-tight">
352	                      {activeItem.name}
353	                    </h2>
354	                    {activeItem.description ? (
355	                      <p className="text-sm text-text-secondary leading-relaxed">
356	                        {activeItem.description}
357	                      </p>
358	                    ) : (
359	                      <p className="text-xs text-text-muted italic">No item details provided.</p>
360	                    )}
361	                  </div>
362	
363	                  {/* Pricing Box */}
364	                  <div className="grid grid-cols-2 gap-4 bg-surface-overlay/60 border border-border/50 p-4 rounded-lg">
365	                    <div>
366	                      <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider block">
367	                        Starting Price
368	                      </span>
369	                      <span className="text-xl font-bold text-text-primary tracking-tight">
370	                        ₹{(activeItem.startingBid ?? 0).toLocaleString()}
371	                      </span>
372	                    </div>
373	                    <div className="border-l border-border/40 pl-4">
374	                      <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider block">
375	                        Highest Bid
376	                      </span>
377	                      <span className="text-xl font-bold text-accent tracking-tight">
378	                        ₹{(activeItem.currentBid ?? activeItem.startingBid ?? 0).toLocaleString()}
379	                      </span>
380	                      {activeItem.highestBidderUsername ? (
381	                        <span className="text-[10px] font-medium text-green-400 block mt-0.5 truncate">
382	                          by {activeItem.highestBidderUsername}
383	                        </span>
384	                      ) : (
385	                        <span className="text-[10px] text-text-muted block mt-0.5">
386	                          No bids placed
387	                        </span>
388	                      )}
389	                    </div>
390	                  </div>
391	                </div>
392	              )}
393	            </div>
394	
395	            {/* Bidding Placement input Box (Visible to Bidders only) */}
396	            {!isAdmin && activeItem && secondsRemaining > 0 && (
397	              <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg">
398	                <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
399	                  <DollarSign className="h-4 w-4 text-accent" />
400	                  Place Bid
401	                </span>
402	
403	                <form onSubmit={handleSubmitBid} className="space-y-4">
404	                  {(localBidErr || bidError) && (
405	                    <div className="flex items-start gap-2.5 rounded-lg border border-red-500/20 bg-red-500/10 p-3 text-xs text-red-400">
406	                      <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
407	                      <p>{localBidErr || bidError?.reason}</p>
408	                    </div>
409	                  )}
410	
411	                  <div className="flex flex-col sm:flex-row gap-3">
412	                    <div className="relative flex-1">
413	                      <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-text-muted">₹</span>
414	                      <input
415	                        type="number"
416	                        required
417	                        min={minBidVal}
418	                        placeholder={`Min bid required: ₹${(minBidVal ?? 1).toLocaleString()}`}
419	                        value={bidVal}
420	                        onChange={(e) => {
421	                          setBidVal(e.target.value);
422	                          setLocalBidErr(null);
423	                        }}
424	                        className="w-full bg-surface-overlay border border-border/80 focus:border-accent/50 focus:ring-1 focus:ring-accent/20 rounded-lg pl-8 pr-4 py-2.5 text-sm text-text-primary placeholder:text-text-muted transition-all outline-none"
425	                      />
426	                    </div>
427	                    <Button type="submit" variant="primary" className="py-2.5 px-6 font-bold text-sm">
428	                      Submit Bid
429	                    </Button>
430	                  </div>
431	                </form>
432	              </div>
433	            )}
434	          </div>
435	
436	          {/* Sidebar Section (1/3 width) */}
437	          <div className="space-y-6">
438	            
439	            {/* Bid History list timeline */}
440	            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg min-h-[220px] flex flex-col">
441	              <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
442	                <TrendingUp className="h-4 w-4 text-accent" />
443	                Live Bids Log ({bids.length})
444	              </span>
445	
446	              {bids.length === 0 ? (
447	                <div className="flex-1 flex flex-col items-center justify-center text-center p-4 space-y-1 text-text-muted">
448	                  <DollarSign className="h-6 w-6 stroke-[1.5]" />
449	                  <p className="text-xs">No bids logged yet</p>
450	                </div>
451	              ) : (
452	                <div className="space-y-2.5 flex-1 overflow-y-auto max-h-[220px] pr-1">
453	                  {bids.map((b) => (
454	                    <div
455	                      key={b._id}
456	                      className="flex items-center justify-between bg-surface-overlay/40 border border-border/30 px-3 py-2 rounded-lg text-xs"
457	                    >
458	                      <div className="flex items-center gap-2 overflow-hidden">
459	                        <div className="h-5 w-5 rounded-full bg-accent/10 flex items-center justify-center font-bold text-[9px] text-accent shrink-0">
460	                          {b.username.charAt(0).toUpperCase()}
461	                        </div>
462	                        <span className="font-semibold text-text-primary truncate">{b.username}</span>
463	                      </div>
464	                      <span className="font-bold text-accent shrink-0">
465	                        ₹{b.amount.toLocaleString()}
466	                      </span>
467	                    </div>
468	                  ))}
469	                </div>
470	              )}
471	            </div>
472	
473	            {/* Bidders Connection Sidebar */}
474	            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg flex flex-col">
475	              <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
476	                <Users className="h-4 w-4 text-accent" />
477	                Lobby Presence ({participants.length})
478	              </span>
479	
480	              <div className="space-y-2.5 max-h-[180px] overflow-y-auto pr-1">
481	                {participants.map((p) => (
482	                  <div
483	                    key={p._id}
484	                    className="flex items-center justify-between bg-surface-overlay/20 border border-border/30 p-2.5 rounded-lg text-xs"
485	                  >
486	                    <div className="flex items-center gap-2 overflow-hidden">
487	                      <div className="h-5.5 w-5.5 rounded-full bg-surface-overlay border border-border flex items-center justify-center font-medium text-[9px] text-text-secondary shrink-0">
488	                        {p.username.charAt(0).toUpperCase()}
489	                      </div>
490	                      <div className="overflow-hidden">
491	                        <p className="font-semibold text-text-primary truncate">
492	                          {p.username}
493	                          {p.username === sessionUsername && (
494	                            <span className="ml-1 text-[8px] text-text-muted">(You)</span>
495	                          )}
496	                        </p>
497	                      </div>
498	                    </div>
499	
500	                    {p.isConnected ? (
501	                      <span className="inline-flex h-2 w-2 rounded-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]" />
502	                    ) : (
503	                      <span className="inline-flex h-2 w-2 rounded-full bg-zinc-500" />
504	                    )}
505	                  </div>
506	                ))}
507	              </div>
508	            </div>
509	
