import { useState, useEffect, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Clock,
  Crown,
  Users,
  AlertCircle,
  Tag,
  MessageSquare,
  DollarSign,
  TrendingUp,
} from "lucide-react";
import { PageContainer } from "../../components/ui/PageContainer";
import { Button } from "../../components/ui/Button";
import { useSessionStore } from "../../stores/useSessionStore";
import { useSocket } from "../../hooks/useSocket";
import { getSocket } from "../../services/socket";
import type { AuctionItem, Bid } from "../../services/api";

interface ToastMsg {
  id: string;
  message: string;
  type: "info" | "success" | "error";
}

export function AuctionPage() {
  const { code } = useParams<{ code: string }>();
  const navigate = useNavigate();

  const {
    roomCode: sessionRoomCode,
    username: sessionUsername,
    role: sessionRole,
    clearSession,
  } = useSessionStore();

  // Connect to Socket.IO to track live bidding item, presence, and bids history
  const {
    status: socketStatus,
    room,
    participants,
    activeItem,
    bids,
    bidError,
    setBidError,
    error: socketError,
  } = useSocket(code || "");

  const [bidVal, setBidVal] = useState("");
  const [localBidErr, setLocalBidErr] = useState<string | null>(null);

  const [toasts, setToasts] = useState<ToastMsg[]>([]);
  const [activityLogs, setActivityLogs] = useState<string[]>([]);
  const [clockNow, setClockNow] = useState(() => Date.now());

  const addToast = useCallback((message: string, type: "info" | "success" | "error" = "info") => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  }, []);

  const minBidVal = activeItem ? (activeItem.currentBid ?? activeItem.startingBid ?? 0) + 1 : 1;
  const endsAtMs = room?.endsAt ? Date.parse(room.endsAt) : Number.NaN;
  const secondsRemaining = Number.isFinite(endsAtMs)
    ? Math.max(0, Math.ceil((endsAtMs - clockNow) / 1000))
    : 0;

  useEffect(() => {
    if (!Number.isFinite(endsAtMs)) return;
    const interval = window.setInterval(() => setClockNow(Date.now()), 250);
    return () => window.clearInterval(interval);
  }, [endsAtMs]);

  // Listen to live events for broadcast logs and toast notifications
  useEffect(() => {
    const socket = getSocket();
    if (!socket) return;

    const handleItemEnded = (data: { item: AuctionItem; resolution: "sold" | "unsold" }) => {
      const username = data.item.highestBidderUsername || "none";
      const price = data.item.currentBid || data.item.startingBid;
      const formattedMsg = data.resolution === "sold"
        ? `${data.item.name} sold to ${username} for ₹${price.toLocaleString()}`
        : `${data.item.name} marked unsold`;

      setActivityLogs((prev) => [...prev, `✦ ${formattedMsg}`]);
      addToast(formattedMsg, "info");
    };

    const handleItemActivated = (data: { item: AuctionItem }) => {
      const msg = `Item ${data.item.name} is active. Minimum bid: ₹${(data.item.currentBid || data.item.startingBid).toLocaleString()}`;
      setActivityLogs((prev) => [...prev, `✦ ${msg}`]);
      addToast(`New item active: ${data.item.name}`, "info");
      setLocalBidErr(null);
      setBidVal("");
    };

    const handleBidAccepted = (data: { bid: Bid }) => {
      const msg = `Bid of ₹${data.bid.amount.toLocaleString()} accepted for ${data.bid.username}`;
      setActivityLogs((prev) => [...prev, `✔ ${msg}.`]);
      addToast(`New bid: ₹${data.bid.amount.toLocaleString()} by ${data.bid.username}`, "success");
    };

    const handleBidRejected = (data: { reason: string; minimumBid: number }) => {
      addToast(data.reason, "error");
    };

    const handleServerError = (data: { message: string }) => addToast(data.message, "error");

    socket.on("item:ended", handleItemEnded);
    socket.on("item:activated", handleItemActivated);
    socket.on("bid:accepted", handleBidAccepted);
    socket.on("bid:rejected", handleBidRejected);
    socket.on("error", handleServerError);

    return () => {
      socket.off("item:ended", handleItemEnded);
      socket.off("item:activated", handleItemActivated);
      socket.off("bid:accepted", handleBidAccepted);
      socket.off("bid:rejected", handleBidRejected);
      socket.off("error", handleServerError);
    };
  }, [addToast]);

  // Security check: Redirect if the user has no session or is in the wrong room
  const hasNoAccess = !sessionUsername || !sessionRole || sessionRoomCode !== code;

  // Automatically navigate to results page when room transitions to completed status
  useEffect(() => {
    if (room?.status === "completed" && code) {
      navigate(`/results/${code}`);
    }
  }, [room?.status, code, navigate]);

  const handleLeaveRoom = () => {
    clearSession();
    navigate("/");
  };

  // Submit new bid (Participants only)
  const handleSubmitBid = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeItem) return;

    const bidAmount = Number(bidVal);
    const currentPrice = activeItem.currentBid ?? activeItem.startingBid ?? 0;
    const minBidRequired = currentPrice + 1;

    if (!Number.isFinite(bidAmount) || bidAmount < minBidRequired) {
      setLocalBidErr(`Bid must be at least ₹${minBidRequired.toLocaleString()}`);
      return;
    }

    setLocalBidErr(null);
    setBidError(null);

    const socket = getSocket();
    if (socket) {
      socket.emit("bid:place", { amount: bidAmount });
    }
    setBidVal(""); // Reset input field
  };

  // Sell active item (Admin only)
  const handleSellItem = () => {
    const socket = getSocket();
    if (socket) {
      socket.emit("item:sell");
    }
  };

  // Mark active item unsold (Admin only)
  const handleMarkUnsold = () => {
    const socket = getSocket();
    if (socket) {
      socket.emit("item:unsold");
    }
  };

  const isLoading = !room && socketStatus === "connecting";

  if (isLoading) {
    return (
      <PageContainer className="flex flex-col items-center justify-center min-h-[60vh] px-4">
        <div className="flex flex-col items-center gap-4 text-center">
          <div className="relative flex h-12 w-12 items-center justify-center">
            <div className="animate-ping absolute inline-flex h-full w-full rounded-full bg-accent/20 opacity-75" />
            <div className="relative rounded-full h-8 w-8 bg-accent/20 flex items-center justify-center">
              <Clock className="h-4 w-4 text-accent animate-spin" />
            </div>
          </div>
          <p className="text-sm text-text-secondary">Establishing live auction connection...</p>
        </div>
      </PageContainer>
    );
  }

  if (socketError || (!room && socketStatus === "disconnected")) {
    return (
      <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
        <div className="border border-border bg-surface-raised/40 p-8 rounded-xl text-center max-w-md mx-auto space-y-6 shadow-xl">
          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-red-500/10 text-red-400">
            <AlertCircle className="h-6 w-6" />
          </div>
          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-text-primary">Realtime Connection Failed</h2>
            <p className="text-sm text-text-secondary leading-relaxed">
              {socketError ?? "Failed to connect to the live auction room. Check if the server is running."}
            </p>
          </div>
          <Button variant="secondary" onClick={() => navigate("/")} className="w-full">
            Back to Home
          </Button>
        </div>
      </PageContainer>
    );
  }

  if (hasNoAccess) {
    return (
      <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
        <div className="border border-border bg-surface-raised/40 p-8 rounded-xl text-center max-w-md mx-auto space-y-6 shadow-xl">
          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-accent/10 text-accent">
            <Users className="h-6 w-6" />
          </div>
          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-text-primary">Access Denied</h2>
            <p className="text-sm text-text-secondary leading-relaxed">
              You are trying to access room <span className="font-mono text-accent font-semibold">{code}</span> but do not have an active session. Please register to join.
            </p>
          </div>
          <Button variant="primary" onClick={() => navigate(`/join?code=${code}`)} className="w-full">
            Join Room
          </Button>
        </div>
      </PageContainer>
    );
  }

  const isAdmin = sessionRole === "admin";

  return (
    <PageContainer className="px-4 py-12 sm:px-6 sm:py-16 max-w-5xl">
      <div className="space-y-8">

        {/* Connection status header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-border pb-6">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="inline-flex h-2 w-2 rounded-full bg-red-500 animate-pulse" />
              <span className="text-[10px] font-semibold uppercase tracking-wider text-red-500 mr-2">
                LIVE AUCTION
              </span>
              <span className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[10px] font-semibold ${secondsRemaining <= 10 ? "border-red-500/30 bg-red-500/10 text-red-400" : "border-accent/30 bg-accent/10 text-accent"}`}>
                <Clock className="h-3 w-3" />
                {secondsRemaining}s
              </span>
              {socketStatus === "connected" && (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-green-500/10 border border-green-500/20 px-2 py-0.5 text-[10px] font-semibold text-green-400">
                  <span className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />
                  Synced
                </span>
              )}
              {socketStatus === "connecting" && (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-500/10 border border-amber-500/20 px-2 py-0.5 text-[10px] font-semibold text-amber-400">
                  <span className="h-1.5 w-1.5 rounded-full bg-amber-500 animate-pulse" />
                  Reconnecting...
                </span>
              )}
            </div>
            <h1 className="text-2xl font-bold tracking-tight text-text-primary sm:text-3xl">
              {room?.name}
            </h1>
          </div>

          <Button
            variant="ghost"
            onClick={handleLeaveRoom}
            className="self-start sm:self-center border border-border/50 text-xs text-text-secondary hover:text-red-400 hover:bg-red-500/10 hover:border-red-500/20"
          >
            Leave Room
          </Button>
        </div>

        {/* Host Control center resolving controls (Visible to Admin only) */}
        {isAdmin && activeItem && (
          <div className="border border-amber-500/20 bg-amber-500/5 p-4 rounded-xl flex flex-col sm:flex-row items-center justify-between gap-4 shadow-sm">
            <div className="space-y-1 text-center sm:text-left">
              <h3 className="text-sm font-semibold text-amber-400 flex items-center justify-center sm:justify-start gap-1.5">
                <Crown className="h-4 w-4" />
                Host Resolution Console
              </h3>
              <p className="text-xs text-text-secondary">
                Resolve the current item's bid. The next pending item in queue will activate automatically.
              </p>
            </div>
            <div className="flex gap-2 w-full sm:w-auto">
              <Button
                onClick={handleSellItem}
                variant="primary"
                className="flex-1 sm:flex-initial bg-green-500 hover:bg-green-600 border-green-500/20 text-zinc-950 font-bold text-xs"
              >
                Sell Item (₹{(activeItem.currentBid ?? activeItem.startingBid ?? 0).toLocaleString()})
              </Button>
              <Button
                onClick={handleMarkUnsold}
                variant="secondary"
                className="flex-1 sm:flex-initial text-xs border border-border/50"
              >
                Mark Unsold
              </Button>
            </div>
          </div>
        )}

        {/* Live Auction Board Layout */}
        <div className="grid gap-6 md:grid-cols-3 items-start">

          {/* Active Item Container (2/3 width) */}
          <div className="md:col-span-2 space-y-6">

            {/* Current Item Presentation */}
            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-6 shadow-lg relative overflow-hidden">
              <div className="absolute top-0 right-0 h-32 w-32 rounded-full bg-accent/5 blur-[30px] pointer-events-none" />

              <div className="flex items-center justify-between border-b border-border/40 pb-4">
                <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2">
                  <Tag className="h-4 w-4 text-accent" />
                  Active Auction Item
                </span>
                {activeItem && secondsRemaining > 0 && (
                  <span className="inline-flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider text-green-400 bg-green-500/15 border border-green-500/30 px-2.5 py-0.5 rounded-full">
                    Bidding Open
                  </span>
                )}
              </div>

              {!activeItem ? (
                <div className="py-12 text-center space-y-3">
                  <Clock className="h-10 w-10 text-text-muted mx-auto animate-pulse" />
                  <h3 className="text-base font-semibold text-text-primary">Waiting for item activation...</h3>
                  <p className="text-xs text-text-secondary max-w-sm mx-auto">
                    The host is resolving items. Bidding will open immediately once the next item activates.
                  </p>
                </div>
              ) : (
                <div className="space-y-6">
                  <div className="space-y-2">
                    <h2 className="text-xl font-bold text-text-primary tracking-tight">
                      {activeItem.name}
                    </h2>
                    {activeItem.description ? (
                      <p className="text-sm text-text-secondary leading-relaxed">
                        {activeItem.description}
                      </p>
                    ) : (
                      <p className="text-xs text-text-muted italic">No item details provided.</p>
                    )}
                  </div>

                  {/* Pricing Box */}
                  <div className="grid grid-cols-2 gap-4 bg-surface-overlay/60 border border-border/50 p-4 rounded-lg">
                    <div>
                      <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider block">
                        Starting Price
                      </span>
                      <span className="text-xl font-bold text-text-primary tracking-tight">
                        ₹{(activeItem.startingBid ?? 0).toLocaleString()}
                      </span>
                    </div>
                    <div className="border-l border-border/40 pl-4">
                      <span className="text-[10px] font-semibold text-text-muted uppercase tracking-wider block">
                        Highest Bid
                      </span>
                      <span className="text-xl font-bold text-accent tracking-tight">
                        ₹{(activeItem.currentBid ?? activeItem.startingBid ?? 0).toLocaleString()}
                      </span>
                      {activeItem.highestBidderUsername ? (
                        <span className="text-[10px] font-medium text-green-400 block mt-0.5 truncate">
                          by {activeItem.highestBidderUsername}
                        </span>
                      ) : (
                        <span className="text-[10px] text-text-muted block mt-0.5">
                          No bids placed
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Bidding Placement input Box (Visible to Bidders only) */}
            {!isAdmin && activeItem && secondsRemaining > 0 && (
              <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg">
                <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
                  <DollarSign className="h-4 w-4 text-accent" />
                  Place Bid
                </span>

                <form onSubmit={handleSubmitBid} className="space-y-4">
                  {(localBidErr || bidError) && (
                    <div className="flex items-start gap-2.5 rounded-lg border border-red-500/20 bg-red-500/10 p-3 text-xs text-red-400">
                      <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
                      <p>{localBidErr || bidError?.reason}</p>
                    </div>
                  )}

                  <div className="flex flex-col sm:flex-row gap-3">
                    <div className="relative flex-1">
                      <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-sm text-text-muted">₹</span>
                      <input
                        type="number"
                        required
                        min={minBidVal}
                        placeholder={`Min bid required: ₹${(minBidVal ?? 1).toLocaleString()}`}
                        value={bidVal}
                        onChange={(e) => {
                          setBidVal(e.target.value);
                          setLocalBidErr(null);
                        }}
                        className="w-full bg-surface-overlay border border-border/80 focus:border-accent/50 focus:ring-1 focus:ring-accent/20 rounded-lg pl-8 pr-4 py-2.5 text-sm text-text-primary placeholder:text-text-muted transition-all outline-none"
                      />
                    </div>
                    <Button type="submit" variant="primary" className="py-2.5 px-6 font-bold text-sm">
                      Submit Bid
                    </Button>
                  </div>
                </form>
              </div>
            )}
          </div>

          {/* Sidebar Section (1/3 width) */}
          <div className="space-y-6">

            {/* Bid History list timeline */}
            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg min-h-[220px] flex flex-col">
              <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
                <TrendingUp className="h-4 w-4 text-accent" />
                Live Bids Log ({bids.length})
              </span>

              {bids.length === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center text-center p-4 space-y-1 text-text-muted">
                  <DollarSign className="h-6 w-6 stroke-[1.5]" />
                  <p className="text-xs">No bids logged yet</p>
                </div>
              ) : (
                <div className="space-y-2.5 flex-1 overflow-y-auto max-h-[220px] pr-1">
                  {bids.map((b) => (
                    <div
                      key={b._id}
                      className="flex items-center justify-between bg-surface-overlay/40 border border-border/30 px-3 py-2 rounded-lg text-xs"
                    >
                      <div className="flex items-center gap-2 overflow-hidden">
                        <div className="h-5 w-5 rounded-full bg-accent/10 flex items-center justify-center font-bold text-[9px] text-accent shrink-0">
                          {b.username.charAt(0).toUpperCase()}
                        </div>
                        <span className="font-semibold text-text-primary truncate">{b.username}</span>
                      </div>
                      <span className="font-bold text-accent shrink-0">
                        ₹{b.amount.toLocaleString()}
                      </span>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Bidders Connection Sidebar */}
            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg flex flex-col">
              <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
                <Users className="h-4 w-4 text-accent" />
                Lobby Presence ({participants.length})
              </span>

              <div className="space-y-2.5 max-h-[180px] overflow-y-auto pr-1">
                {participants.map((p) => (
                  <div
                    key={p._id}
                    className="flex items-center justify-between bg-surface-overlay/20 border border-border/30 p-2.5 rounded-lg text-xs"
                  >
                    <div className="flex items-center gap-2 overflow-hidden">
                      <div className="h-5.5 w-5.5 rounded-full bg-surface-overlay border border-border flex items-center justify-center font-medium text-[9px] text-text-secondary shrink-0">
                        {p.username.charAt(0).toUpperCase()}
                      </div>
                      <div className="overflow-hidden">
                        <p className="font-semibold text-text-primary truncate">
                          {p.username}
                          {p.username === sessionUsername && (
                            <span className="ml-1 text-[8px] text-text-muted">(You)</span>
                          )}
                        </p>
                      </div>
                    </div>

                    {p.isConnected ? (
                      <span className="inline-flex h-2 w-2 rounded-full bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.5)]" />
                    ) : (
                      <span className="inline-flex h-2 w-2 rounded-full bg-zinc-500" />
                    )}
                  </div>
                ))}
              </div>
            </div>

            {/* Notification logs panel */}
            <div className="border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg">
              <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
                <MessageSquare className="h-4 w-4 text-accent" />
                Live Broadcasts
              </span>

              <div className="h-32 overflow-y-auto space-y-2 text-[10px] text-text-muted pr-1">
                {activityLogs.length === 0 ? (
                  <p className="text-text-muted italic">Waiting for room activity...</p>
                ) : (
                  activityLogs.map((log, index) => {
                    const isSuccess = log.includes("✔");
                    return (
                      <p
                        key={index}
                        className={isSuccess ? "text-green-400" : "text-text-secondary font-medium"}
                      >
                        {log}
                      </p>
                    );
                  })
                )}
              </div>
            </div>

          </div>
        </div>
      </div>

      {/* Floating Toast Notification Container */}
      <div className="fixed top-6 right-6 z-50 flex flex-col gap-3 max-w-sm w-full pointer-events-none">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className={`pointer-events-auto p-4 rounded-xl border bg-zinc-950/90 backdrop-blur-md shadow-2xl flex items-center gap-3 transition-all transform duration-300 ${
              toast.type === "error"
                ? "border-red-500/30 text-red-400"
                : toast.type === "success"
                ? "border-green-500/30 text-green-400"
                : "border-border text-text-primary"
            }`}
          >
            <span className="text-xs font-semibold">{toast.message}</span>
          </div>
        ))}
      </div>
    </PageContainer>
  );
}

import { useState, useEffect } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  Copy,
  Check,
  LogOut,
  Clock,
  Users,
  Crown,
  AlertCircle,
  Tag,
  PlusCircle,
  FileText,
} from "lucide-react";
import { PageContainer } from "../components/ui/PageContainer";
import { Button } from "../components/ui/Button";
import { useSessionStore } from "../stores/useSessionStore";
import { useSocket } from "../hooks/useSocket";
import { addAuctionItem } from "../services/api";
import { getSocket } from "../services/socket";
import { getErrorMessage } from "../utils/error";

export function LobbyPage() {
  const { code } = useParams<{ code: string }>();
  const navigate = useNavigate();

  const {
    roomCode: sessionRoomCode,
    username: sessionUsername,
    role: sessionRole,
    sessionToken,
    clearSession,
  } = useSessionStore();

  // Connect to the socket server to sync room and items state in realtime
  const {
    status: socketStatus,
    room,
    participants,
    items,
    error: socketError,
  } = useSocket(code || "");

  const [copied, setCopied] = useState(false);

  // Admin Item Form State
  const [itemName, setItemName] = useState("");
  const [itemDesc, setItemDesc] = useState("");
  const [itemBid, setItemBid] = useState("");
  const [itemLoading, setItemLoading] = useState(false);
  const [itemError, setItemError] = useState<string | null>(null);
  const [itemSuccess, setItemSuccess] = useState(false);

  // Security check: Redirect if the user has no session or is in the wrong room
  const hasNoAccess = !sessionUsername || !sessionRole || sessionRoomCode !== code;

  const handleCopyCode = async () => {
    if (!code) return;
    try {
      await navigator.clipboard.writeText(code);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error("Failed to copy text: ", err);
    }
  };

  const handleLeaveRoom = () => {
    clearSession();
    navigate("/");
  };

  // Submit new auction item (Admin only)
  const handleAddItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!code || !sessionToken) return;

    if (!itemName.trim()) {
      setItemError("Item name is required.");
      return;
    }
    const bidAmount = Number(itemBid);
    if (isNaN(bidAmount) || bidAmount <= 0) {
      setItemError("Starting bid must be positive.");
      return;
    }

    setItemLoading(true);
    setItemError(null);
    setItemSuccess(false);

    try {
      await addAuctionItem(
        code,
        sessionToken,
        itemName.trim(),
        itemDesc.trim(),
        bidAmount
      );

      // Clear form on success
      setItemName("");
      setItemDesc("");
      setItemBid("");
      setItemSuccess(true);
      setTimeout(() => setItemSuccess(false), 3000);
    } catch (err: unknown) {
      setItemError(getErrorMessage(err, "Failed to add item."));
    } finally {
      setItemLoading(false);
    }
  };

  // Redirect to live auction page when the room transitions to active/live status
  useEffect(() => {
    if (room?.status === "live" && code) {
      navigate(`/auction/${code}`);
    }
  }, [room?.status, code, navigate]);

  // Request the server to start the auction (Admin only)
  const handleStartAuction = () => {
    const socket = getSocket();
    if (socket) {
      socket.emit("auction:start");
    }
  };

  // Show dynamic loader until we get the room details from the socket room state
  const isLoading = !room && socketStatus === "connecting";

  if (isLoading) {
    return (
      <PageContainer className="flex flex-col items-center justify-center min-h-[60vh] px-4">
        <div className="flex flex-col items-center gap-4 text-center">
          <div className="relative flex h-12 w-12 items-center justify-center">
            <div className="animate-ping absolute inline-flex h-full w-full rounded-full bg-accent/20 opacity-75" />
            <div className="relative rounded-full h-8 w-8 bg-accent/20 flex items-center justify-center">
              <Clock className="h-4 w-4 text-accent animate-spin" />
            </div>
          </div>
          <p className="text-sm text-text-secondary">Establishing realtime server connection...</p>
        </div>
      </PageContainer>
    );
  }

  if (socketError || (!room && socketStatus === "disconnected")) {
    return (
      <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
        <div className="border border-border bg-surface-raised/40 p-8 rounded-xl text-center max-w-md mx-auto space-y-6 shadow-xl">
          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-red-500/10 text-red-400">
            <AlertCircle className="h-6 w-6" />
          </div>
          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-text-primary">Realtime Connection Failed</h2>
            <p className="text-sm text-text-secondary leading-relaxed">
              {socketError ?? "Failed to connect to the realtime lobby server. Check if the server is running."}
            </p>
          </div>
          <Button variant="secondary" onClick={() => navigate("/")} className="w-full">
            Back to Home
          </Button>
        </div>
      </PageContainer>
    );
  }

  if (hasNoAccess) {
    return (
      <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
        <div className="border border-border bg-surface-raised/40 p-8 rounded-xl text-center max-w-md mx-auto space-y-6 shadow-xl">
          <div className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-accent/10 text-accent">
            <Users className="h-6 w-6" />
          </div>
          <div className="space-y-2">
            <h2 className="text-xl font-semibold text-text-primary">Unauthorized Access</h2>
            <p className="text-sm text-text-secondary leading-relaxed">
              You are trying to access room <span className="font-mono text-accent font-semibold">{code}</span> but do not have an active session. Please join the room with a username to proceed.
            </p>
          </div>
          <Button variant="primary" onClick={() => navigate(`/join?code=${code}`)} className="w-full">
            Join Room
          </Button>
        </div>
      </PageContainer>
    );
  }

  const isAdmin = sessionRole === "admin";

  return (
    <PageContainer className="px-4 py-12 sm:px-6 sm:py-16">
      <div className="mx-auto max-w-4xl w-full space-y-8">

        {/* Connection status header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-border pb-6">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              {socketStatus === "connected" && (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-green-500/10 border border-green-500/20 px-2.5 py-0.5 text-[11px] font-semibold text-green-400">
                  <span className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />
                  Realtime Synced
                </span>
              )}
              {socketStatus === "connecting" && (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-amber-500/10 border border-amber-500/20 px-2.5 py-0.5 text-[11px] font-semibold text-amber-400">
                  <span className="h-1.5 w-1.5 rounded-full bg-amber-500 animate-pulse" />
                  Reconnecting...
                </span>
              )}
              {socketStatus === "disconnected" && (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-red-500/10 border border-red-500/20 px-2.5 py-0.5 text-[11px] font-semibold text-red-400">
                  <span className="h-1.5 w-1.5 rounded-full bg-red-500" />
                  Offline
                </span>
              )}
            </div>
            <h1 className="text-2xl font-bold tracking-tight text-text-primary sm:text-3xl">
              {room?.name}
            </h1>
          </div>

          <Button
            variant="ghost"
            onClick={handleLeaveRoom}
            className="self-start sm:self-center border border-border/50 text-xs text-text-secondary hover:text-red-400 hover:bg-red-500/10 hover:border-red-500/20"
          >
            <LogOut className="h-3.5 w-3.5" />
            Leave Lobby
          </Button>
        </div>

        {/* Host Control Center banner */}
        {isAdmin && (
          <div className="border border-amber-500/20 bg-amber-500/5 p-4 rounded-xl flex flex-col sm:flex-row items-center justify-between gap-4 shadow-sm animate-fade-in-up">
            <div className="space-y-1">
              <h3 className="text-sm font-semibold text-amber-400 flex items-center gap-1.5">
                <Crown className="h-4 w-4" />
                Host Control Center
              </h3>
              <p className="text-xs text-text-secondary">
                Prepare your catalog. Once participants have joined, click the button to launch the live auction timer.
              </p>
            </div>
            <Button
              onClick={handleStartAuction}
              disabled={items.length === 0}
              variant="primary"
              className="w-full sm:w-auto bg-amber-500 hover:bg-amber-600 border-amber-500/20 shadow-[0_0_15px_rgba(245,158,11,0.15)] text-zinc-950 font-bold cursor-pointer"
            >
              Start Live Auction
            </Button>
          </div>
        )}

        {/* Dashboard Room/Profile Info */}
        <div className="grid gap-6 sm:grid-cols-5">
          {/* Room Details Card (3/5 width) */}
          <div className="sm:col-span-3 border border-border bg-surface-raised/40 backdrop-blur-md p-6 rounded-xl space-y-6 flex flex-col justify-between shadow-lg">
            <div className="space-y-1.5">
              <span className="text-xs font-semibold uppercase tracking-wider text-text-muted">
                Invite Code
              </span>
              <p className="text-sm text-text-secondary leading-relaxed">
                Share this code with other users to let them join this room in realtime.
              </p>
            </div>

            <div className="flex items-center gap-2 bg-surface-overlay/80 border border-border/60 p-3 rounded-lg font-mono">
              <span className="text-2xl font-bold tracking-widest text-text-primary flex-1 text-center">
                {code}
              </span>
              <button
                onClick={handleCopyCode}
                className="flex h-10 w-10 items-center justify-center rounded-md border border-border bg-surface-raised transition-all hover:bg-surface-overlay hover:border-accent"
                title="Copy code"
              >
                {copied ? (
                  <Check className="h-4 w-4 text-green-400" />
                ) : (
                  <Copy className="h-4 w-4 text-text-secondary" />
                )}
              </button>
            </div>
          </div>

          {/* User Profile Card (2/5 width) */}
          <div className="sm:col-span-2 border border-border bg-surface-raised/40 backdrop-blur-md p-6 rounded-xl space-y-6 flex flex-col justify-between shadow-lg">
            <div className="space-y-1.5">
              <span className="text-xs font-semibold uppercase tracking-wider text-text-muted">
                Your Connection
              </span>
              <p className="text-sm text-text-secondary leading-relaxed">
                Your active profile in this bidding room.
              </p>
            </div>

            <div className="space-y-3 bg-surface-overlay/40 border border-border/40 p-4 rounded-lg">
              <div className="flex items-center gap-2.5">
                <div className="flex h-8 w-8 items-center justify-center rounded-full bg-accent/15 text-accent font-semibold text-sm">
                  {sessionUsername?.charAt(0).toUpperCase()}
                </div>
                <div className="flex-1 overflow-hidden">
                  <h4 className="text-sm font-semibold text-text-primary truncate">
                    {sessionUsername}
                  </h4>
                  <p className="text-xs text-text-muted truncate">Realtime Active</p>
                </div>
              </div>

              <div className="border-t border-border/30 pt-2.5 flex items-center justify-between">
                <span className="text-xs text-text-muted">Role</span>
                {sessionRole === "admin" ? (
                  <span className="inline-flex items-center gap-1 text-xs font-medium text-amber-400 bg-amber-500/10 border border-amber-500/20 px-2 py-0.5 rounded-full">
                    <Crown className="h-3 w-3" />
                    Room Host
                  </span>
                ) : (
                  <span className="inline-flex items-center gap-1 text-xs font-medium text-accent bg-accent/10 border border-accent/20 px-2 py-0.5 rounded-full">
                    <Users className="h-3 w-3" />
                    Bidder
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Realtime Catalog & Admin Form */}
        <div className="grid gap-6 md:grid-cols-5 items-start">

          {/* Upcoming Items List (3/5 width) */}
          <div className={`${isAdmin ? "md:col-span-3" : "md:col-span-5"} border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg min-h-[300px] flex flex-col`}>
            <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
              <Tag className="h-4 w-4 text-accent" />
              Upcoming Auction Items ({items.length})
            </span>

            {items.length === 0 ? (
              <div className="flex-1 flex flex-col items-center justify-center text-center p-8 space-y-2">
                <FileText className="h-8 w-8 text-text-muted stroke-[1.5]" />
                <p className="text-sm font-medium text-text-secondary">No items added yet</p>
                <p className="text-xs text-text-muted leading-relaxed max-w-xs">
                  {isAdmin
                    ? "Add items on the side panel to prepare the auction list."
                    : "The host is preparing the catalog. Items added will appear here instantly."}
                </p>
              </div>
            ) : (
              <div className="space-y-3 max-h-[400px] overflow-y-auto pr-1">
                {items.map((item) => (
                  <div
                    key={item._id}
                    className="border border-border/50 bg-surface-overlay/50 p-4 rounded-lg flex justify-between items-start gap-4 transition-all hover:border-accent/30"
                  >
                    <div className="space-y-1 overflow-hidden">
                      <h4 className="text-sm font-semibold text-text-primary truncate">
                        {item.name}
                      </h4>
                      {item.description ? (
                        <p className="text-xs text-text-secondary leading-relaxed line-clamp-2">
                          {item.description}
                        </p>
                      ) : (
                        <p className="text-xs text-text-muted italic">No description provided</p>
                      )}
                    </div>

                    <div className="shrink-0 text-right">
                      <span className="text-xs text-text-muted block">Base Bid</span>
                      <span className="text-sm font-bold text-accent">
                        ₹{item.startingBid.toLocaleString()}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Add Auction Item form (2/5 width, visible to Admin only) */}
          {isAdmin && (
            <div className="md:col-span-2 border border-border bg-surface-raised/40 p-6 rounded-xl space-y-4 shadow-lg">
              <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
                <PlusCircle className="h-4 w-4 text-accent" />
                Add Auction Item
              </span>

              <form onSubmit={handleAddItem} className="space-y-4">
                {itemError && (
                  <div className="flex items-start gap-2.5 rounded-lg border border-red-500/20 bg-red-500/10 p-3 text-xs text-red-400">
                    <AlertCircle className="h-4 w-4 shrink-0 mt-0.5" />
                    <p>{itemError}</p>
                  </div>
                )}
                {itemSuccess && (
                  <div className="flex items-start gap-2.5 rounded-lg border border-green-500/20 bg-green-500/10 p-3 text-xs text-green-400">
                    <Check className="h-4 w-4 shrink-0 mt-0.5" />
                    <p>Item added and synchronized successfully!</p>
                  </div>
                )}

                <div className="space-y-1.5">
                  <label htmlFor="itemName" className="text-xs font-medium text-text-secondary">
                    Item Name
                  </label>
                  <input
                    id="itemName"
                    type="text"
                    required
                    placeholder="e.g. MS Dhoni Signed Bat"
                    value={itemName}
                    onChange={(e) => setItemName(e.target.value)}
                    className="w-full bg-surface-overlay border border-border focus:border-accent/50 focus:ring-1 focus:ring-accent/20 rounded-lg px-3 py-2 text-xs text-text-primary placeholder:text-text-muted transition-all outline-none"
                    disabled={itemLoading}
                  />
                </div>

                <div className="space-y-1.5">
                  <label htmlFor="itemBid" className="text-xs font-medium text-text-secondary">
                    Starting Bid (₹)
                  </label>
                  <input
                    id="itemBid"
                    type="number"
                    required
                    placeholder="e.g. 500"
                    min="1"
                    value={itemBid}
                    onChange={(e) => setItemBid(e.target.value)}
                    className="w-full bg-surface-overlay border border-border focus:border-accent/50 focus:ring-1 focus:ring-accent/20 rounded-lg px-3 py-2 text-xs text-text-primary placeholder:text-text-muted transition-all outline-none"
                    disabled={itemLoading}
                  />
                </div>

                <div className="space-y-1.5">
                  <label htmlFor="itemDesc" className="text-xs font-medium text-text-secondary">
                    Description (Optional)
                  </label>
                  <textarea
                    id="itemDesc"
                    placeholder="e.g. Match-worn and signed collectibles."
                    rows={3}
                    value={itemDesc}
                    onChange={(e) => setItemDesc(e.target.value)}
                    className="w-full bg-surface-overlay border border-border focus:border-accent/50 focus:ring-1 focus:ring-accent/20 rounded-lg px-3 py-2 text-xs text-text-primary placeholder:text-text-muted transition-all outline-none resize-none"
                    disabled={itemLoading}
                  />
                </div>

                <Button
                  type="submit"
                  disabled={itemLoading}
                  className="w-full text-xs py-2"
                  variant="primary"
                >
                  {itemLoading ? (
                    <>
                      <Clock className="h-3.5 w-3.5 animate-spin" />
                      Adding...
                    </>
                  ) : (
                    <>
                      <PlusCircle className="h-3.5 w-3.5" />
                      Register Item
                    </>
                  )}
                </Button>
              </form>
            </div>
          )}
        </div>

        {/* Realtime Active Presence Board */}
        <div className="border border-border bg-surface-raised/35 p-6 rounded-xl space-y-4 shadow-sm">
          <span className="text-xs font-semibold uppercase tracking-wider text-text-secondary flex items-center gap-2 border-b border-border/40 pb-3">
            <Users className="h-3.5 w-3.5 text-accent" />
            Lobby Bidders ({participants.length})
          </span>

          <div className="grid gap-3 sm:grid-cols-2">
            {participants.map((p) => (
              <div
                key={p._id}
                className="flex items-center justify-between bg-surface-overlay/40 border border-border/50 p-3 rounded-lg"
              >
                <div className="flex items-center gap-2.5 overflow-hidden">
                  <div className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-surface-overlay border border-border text-xs text-text-secondary font-medium">
                    {p.username.charAt(0).toUpperCase()}
                  </div>
                  <div className="overflow-hidden">
                    <p className="text-sm font-medium text-text-primary truncate">
                      {p.username}
                      {p.username === sessionUsername && (
                        <span className="ml-1 text-[10px] text-text-muted">(You)</span>
                      )}
                    </p>
                    <div className="flex items-center gap-1.5">
                      {p.role === "admin" ? (
                        <span className="text-[10px] text-amber-400 font-medium">Host</span>
                      ) : (
                        <span className="text-[10px] text-accent font-medium">Bidder</span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="shrink-0">
                  {p.isConnected ? (
                    <span className="inline-flex items-center gap-1 rounded-full bg-green-500/10 px-2 py-0.5 text-[10px] font-medium text-green-400 border border-green-500/20">
                      <span className="h-1 w-1 rounded-full bg-green-500" />
                      Online
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-1 rounded-full bg-zinc-500/10 px-2 py-0.5 text-[10px] font-medium text-text-muted border border-border">
                      <span className="h-1 w-1 rounded-full bg-text-muted/45" />
                      Offline
                    </span>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </PageContainer>
  );
}

