const ids = rooms.map(r => r._id);
for (const c of ["participants","auctionitems","bids"]) {
  const res = await db.collection(c).deleteMany({ roomId: { $in: ids } });
  console.log(`  ${c}: removed ${res.deletedCount}`);
}
console.log("  rooms: removed", (await db.collection("rooms").deleteMany({ _id: { $in: ids } })).deletedCount);
console.log("  users(probe): removed", (await db.collection("users").deleteMany({ usernameNormalized: "probe_tmp_user" })).deletedCount);
console.log("\n--- final state of prod db 'test' ---");
for (const c of ["rooms","participants","auctionitems","bids","users"]) {
  console.log(`  ${c}: ${await db.collection(c).countDocuments()}`);
}
const left = await db.collection("rooms").find({}).project({code:1,name:1,status:1}).toArray();
left.forEach(r => console.log(`     remaining room: ${r.code} "${r.name}" ${r.status}`));
process.exit(0);
EOF
