const runAuthCheck = useCallback(async () => {
  try {
    const data = await checkAuth();
    setAuthUser(data.user ?? null);
    setStatus("ready");
  } catch (error) {
    // An unreachable backend is not the same as a signed-out user: rendering the
    // app would leave every subsequent request failing with no explanation.
    if (error instanceof ApiUnavailableError) {
      setStatus("unavailable");
      return;
    }

    setAuthUser(null);
    setStatus("ready");
  }
}, [setAuthUser]);

// Resetting to the loading state belongs to the retry, not to mount: on mount
// both values already hold these defaults, and setting them synchronously
// inside the effect would force a second render pass before the first paint.
const retry = useCallback(() => {
  setStatus("loading");
  setIsSlow(false);
  void runAuthCheck();
}, [runAuthCheck]);

useEffect(() => {
  void runAuthCheck();
}, [runAuthCheck]);

