  participant: Participant;
  sessionToken: string;
}

export interface JoinResponse {
  room: Room;
  participant: Participant;
  sessionToken: string;
}

export interface AuthResponse {
  username: string;
  role: "admin" | "participant";
}

/**
 * Authentication Endpoints
 */

export async function login(username: string, password?: string): Promise<AuthResponse> {
  const response = await fetch(`${API_URL}/auth/login`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ username, password }),
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to log in.");
  }

  return response.json();
}

export async function register(username: string, password?: string): Promise<AuthResponse> {
  const response = await fetch(`${API_URL}/auth/register`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ username, password }),
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to register.");
  }

  return response.json();
}

export async function logout(): Promise<{ message: string }> {
  const response = await fetch(`${API_URL}/auth/logout`, {
    method: "POST",
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to log out.");
  }

  return response.json();
}

export async function checkAuth(): Promise<{ user: AuthResponse | null }> {
  let response: Response;

  try {
    response = await fetch(`${API_URL}/auth/me`, {
      method: "GET",
      credentials: "include",
      signal: AbortSignal.timeout(COLD_START_TIMEOUT_MS),
    });
  } catch {
    // Network failure, DNS failure, CORS rejection or timeout.
    throw new ApiUnavailableError("Could not reach the server.");
  }

  // 5xx means the backend is up but unhealthy, e.g. its database is unreachable.
  if (response.status >= 500) {
    throw new ApiUnavailableError("The server is not ready yet.");
  }

  if (!response.ok) {
    return { user: null };
  }

  return response.json();
}

/**
 * Room Endpoints
 */

export async function createRoom(
  username: string,
  roomName: string
): Promise<RoomResponse> {
  const response = await fetch(`${API_URL}/rooms`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ username, roomName }),
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to create room");
  }

  return response.json();
}

export async function joinRoom(
  code: string,
  username: string
): Promise<JoinResponse> {
  const response = await fetch(`${API_URL}/rooms/${code.toUpperCase()}/join`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ username }),
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to join room");
  }

  return response.json();
}

export interface AuctionItem {
  _id: string;
  roomId: string;
  name: string;
  description?: string;
  startingBid: number;
  currentBid: number;
  highestBidderId?: string | null;
  highestBidderUsername?: string | null;
  status: "pending" | "active" | "sold" | "unsold";
  endsAt?: string | null;
  createdAt: string;
  updatedAt: string;
}

export async function addAuctionItem(
  code: string,
  sessionToken: string,
  name: string,
  description: string,
  startingBid: number
): Promise<AuctionItem> {
  const response = await fetch(`${API_URL}/rooms/${code.toUpperCase()}/items`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-session-token": sessionToken,
    },
    body: JSON.stringify({ name, description, startingBid }),
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to add auction item.");
  }

  return response.json();
}

export async function getAuctionItems(code: string): Promise<AuctionItem[]> {
  const response = await fetch(`${API_URL}/rooms/${code.toUpperCase()}/items`, {
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to fetch auction items.");
  }

  return response.json();
}

export interface Bid {
  _id: string;
  roomId: string;
  itemId: string;
  participantId: string;
  username: string;
  amount: number;
  createdAt: string;
}

export async function getRoomResults(code: string): Promise<AuctionItem[]> {
  const response = await fetch(`${API_URL}/rooms/${code.toUpperCase()}/results`, {
    credentials: "include",
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.error ?? "Failed to fetch auction results.");
  }

  return response.json();
}

