A.on("bid:rejected", d => { rejected++; console.log("  A rejected:", d.reason); });
B.on("bid:rejected", d => { rejected++; console.log("  B rejected:", d.reason); });
A.on("item:activated", d => console.log("  item:activated ->", d.item.name));
A.on("item:ended", d => console.log("  item:ended ->", d.item.name, d.resolution));
A.on("auction:completed", () => console.log("  auction:completed"));

console.log("start auction");
H.emit("auction:start");
await new Promise(r=>setTimeout(r,1200));

console.log("TEST 1: two identical concurrent bids of 200");
A.emit("bid:place",{amount:200}); B.emit("bid:place",{amount:200});
await new Promise(r=>setTimeout(r,1500));
console.log(`  -> accepted=${accepted} rejected=${rejected} (expect 1 accept broadcast pair, 1 reject)`);

console.log("TEST 2: bid at the last moment must extend, not lose to the stale timer");
await new Promise(r=>setTimeout(r,4200));           // near the 6s deadline
A.emit("bid:place",{amount:500});
await new Promise(r=>setTimeout(r,2500));           // past the ORIGINAL deadline
const still = await fetch(`${BASE}/api/rooms/${code}/items`).then(r=>r.json());
const itemA = still.find(i=>i.name==="Item A");
console.log(`  -> Item A status after original deadline: ${itemA.status} (expect active, extended)`);

console.log("TEST 3: let it expire naturally");
await new Promise(r=>setTimeout(r,7000));
const after = await fetch(`${BASE}/api/rooms/${code}/items`).then(r=>r.json());
console.log("  -> " + after.map(i=>`${i.name}=${i.status}@${i.currentBid}`).join(", "));
process.exit(0);
EOF
