use strict; use warnings;
# Pull live secret values out of the local .env so they can be redacted by value,
# not just by pattern. Never printed.
my %secrets;
if (open my $env, '<', 'backend/.env') {
  while (<$env>) { chomp; next unless /^([A-Z_]+)=(.+)$/; my ($k,$v)=($1,$2);
    if ($k eq 'MONGODB_URI' && $v =~ m{//[^:]+:([^@]+)@}) { $secrets{$1}=1 }
    if ($k eq 'JWT_SECRET') { $secrets{$v}=1 }
  } close $env;
}
my @lit = grep { length($_) > 5 } keys %secrets;
while (my $line = <STDIN>) {
  for my $s (@lit) { my $q = quotemeta $s; $line =~ s/$q/<REDACTED>/g; }
  $line =~ s{mongodb\+srv://[^:\\"]+:[^\@\\"]+\@}{mongodb+srv://<REDACTED>:<REDACTED>\@}g;
  $line =~ s{mongodb://[^:/\\"]+:[^\@\\"]+\@}{mongodb://<REDACTED>:<REDACTED>\@}g;
  $line =~ s/JWT_SECRET=[^\\"\s,}]{4,}/JWT_SECRET=<REDACTED>
  $line =~ s/eyJ[A-Za-z0-9_-]{20,}(?:\.[A-Za-z0-9_-]+){0,2}/<REDACTED_JWT>/g;
  print $line;
}
PERL
